              const programScope = declarationScope.getProgramParent();
              programScope.references[uid] = true;
              programScope.uids[uid] = true;
              id = t.identifier(uid);

              const isFunctionExpr = declaration.isFunctionExpression();
              const isClassExpr = declaration.isClassExpression();
              if (standaloneDeclaration || isFunctionExpr || isClassExpr) {
                const namedId = t.cloneNode(id);
                declaration.node.id = namedId;
              }
            }

