import type Binding from "../binding";
import splitExportDeclaration from "@babel/helper-split-export-declaration";
import * as t from "@babel/types";
import type { NodePath, Visitor } from "../..";
import { requeueComputedKeyAndDecorators } from "@babel/helper-environment-visitor";
import { traverseNode } from "../../traverse-node";
import { explode } from "../../visitors";

const renameVisitor: Visitor<Renamer> = {
  ReferencedIdentifier({ node, parent }, state) {
    if (node.name === state.oldName) {
      node.name = state.newName;
      state.renamedIdentifiers.add(node);
      if (t.isObjectProperty(parent) && parent.shorthand) {
        parent.shorthand = false;
        if (parent.extra?.shorthand) parent.extra.shorthand = false;
      }
    }
  },

  Scope(path, state) {
    if (
      !path.scope.bindingIdentifierEquals(
        state.oldName,
        state.binding.identifier,
      )
    ) {
      path.skip();
      if (path.isMethod()) {
        requeueComputedKeyAndDecorators(path);
      }
    }
  },

  "AssignmentExpression|Declaration|VariableDeclarator"(
    path: NodePath<t.AssignmentPattern | t.Declaration | t.VariableDeclarator>,
    state,
  ) {
    if (path.isVariableDeclaration()) return;
    const ids = path.getOuterBindingIdentifierPaths();

    for (const name in ids) {
      if (name === state.oldName) {
        const id = ids[name];
        id.node.name = state.newName;

        state.renamedIdentifiers.add(id.node);
      }
    }
  },
};

function renameShorthandProperties(
  node: t.Node,
  renamedIdentifiers: WeakSet<t.Identifier>,
) {
  if (
    t.isObjectProperty(node) &&
    node.shorthand &&
    containsRenamedIdentifier(node.value, renamedIdentifiers)
  ) {
    node.shorthand = false;
    if (node.extra?.shorthand) node.extra.shorthand = false;
  }

  for (const key of t.VISITOR_KEYS[node.type]) {
    const child = node[key] as t.Node | t.Node[] | null | undefined;
    if (Array.isArray(child)) {
      for (const childNode of child) {
        renameShorthandProperties(childNode, renamedIdentifiers);
      }
    } else if (child) {
      renameShorthandProperties(child, renamedIdentifiers);
    }
  }
}

function containsRenamedIdentifier(
  node: t.Node,
  renamedIdentifiers: WeakSet<t.Identifier>,
) {
  if (t.isIdentifier(node)) return renamedIdentifiers.has(node);

  return t.VISITOR_KEYS[node.type].some(key => {
    const child = node[key] as t.Node | t.Node[] | null | undefined;
    return Array.isArray(child)
      ? child.some(childNode =>
          containsRenamedIdentifier(childNode, renamedIdentifiers),
        )
      : child && containsRenamedIdentifier(child, renamedIdentifiers);
  });
}

